import raw from "@/data/verse-index.json";

/**
 * A reference-only map of all 657 verses (generated by scripts/build-verse-index.mjs).
 * The picker, go-to box, previous/next and the purport button use it, so none of them
 * has to download a chapter just to know what exists.
 */
export type VerseEntry = {
  reference: string;
  chapter: number;
  /** First verse number of the entry ("1.16-18" → 16). */
  verse: number;
  /** Last verse number of the entry ("1.16-18" → 18). */
  end: number;
  important: boolean;
  purport: { en: boolean; ta: boolean };
};

export const VERSE_INDEX: readonly VerseEntry[] = (raw as [string, number][]).map(([reference, flags]) => {
  const [, chapter, verse, end] = /^(\d+)\.(\d+)(?:-(\d+))?$/.exec(reference)!;
  return { reference, chapter: +chapter, verse: +verse, end: +(end ?? verse), important: !!(flags & 1), purport: { en: !!(flags & 2), ta: !!(flags & 4) } };
});

const BY_REFERENCE = new Map(VERSE_INDEX.map((entry, i) => [entry.reference, i]));

export const indexOfReference = (reference: string): number => BY_REFERENCE.get(reference) ?? -1;

/** Entries grouped by chapter, in reading order. */
export const VERSES_BY_CHAPTER: ReadonlyMap<number, readonly VerseEntry[]> = (() => {
  const map = new Map<number, VerseEntry[]>();
  for (const entry of VERSE_INDEX) map.set(entry.chapter, [...(map.get(entry.chapter) ?? []), entry]);
  return map;
})();

/** Position of the entry that contains chapter.verse, so "13.2" finds the combined "13.1-2" entry. -1 when none. */
export function indexCovering(chapter: number, verse: number): number {
  return VERSE_INDEX.findIndex((e) => e.chapter === chapter && verse >= e.verse && verse <= e.end);
}

export function hasPurport(reference: string, language: "en" | "ta"): boolean {
  const i = BY_REFERENCE.get(reference);
  return i !== undefined && VERSE_INDEX[i].purport[language];
}
